  "steps": [
    {
      "id": 1,
      "claim": "For sound in a stationary medium, the observed frequency is f' = f · (v + v_D) / (v – v_S), where v is the speed of sound, v_D is the detector speed toward the source (positive toward), and v_S is the source speed toward the detector (positive toward).",
      "evidence": "Standard Doppler‑shift formula for waves in a medium.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "No Doppler shift occurs when the numerator equals the denominator, i.e., v + v_D = v – v_S, which simplifies to v_D = –v_S.",
      "evidence": "Algebraic manipulation of the formula in step 1.",
      "weight": 0.30,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The condition v_D = –v_S means the detector must move toward the source with the same speed that the source moves away from the detector (or both are stationary).",
      "evidence": "Interpretation of the sign convention in step 2.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Option (A) has a moving source toward a stationary detector (v_S > 0, v_D = 0), which does not satisfy v_D = –v_S unless v_S = 0, contradicting the wording.",
      "evidence": "Apply condition from step 3 to the velocities described in (A).",
      "weight": 0.10,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Option (B) has a moving detector toward a stationary source (v_D > 0, v_S = 0), which also fails the condition unless v_D = 0.",
      "evidence": "Apply condition from step 3 to (B).",
      "weight": 0.10,
      "depends_on": [3]
    },
    {
      "id": 6,
      "claim": "Option (C) allows both source and detector to travel in the same direction with equal speeds, making their relative speed zero; this fulfills the no‑shift requirement (effectively v_S = v_D, giving v_D = –v_S in the chosen sign convention).",
      "evidence": "When the two move together, the wavelength and arrival rate of wave crests at the detector are unchanged.",
      "weight": 0.15,
      "depends_on": [3]
    },
    {
      "id": 7,
      "claim": "Option (D) has the source and detector moving away from each other, giving v_S > 0 and v_D < 0 (both away), which cannot satisfy v_D = –v_S.",
      "evidence": "Apply condition from step 3 to (D).",
      "weight": 0.05,
      "depends_on": [3]
    }
  ],
  "answer": "C",
  "confidence": 0.96,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Requires the source to be stationary to avoid shift, contradicting the statement that it travels toward the detector."
    },
    {
      "answer": "B",
      "reason_rejected": "Requires the detector to be stationary, contradicting the statement that it travels toward the source."
    },
    {
      "answer": "D",
      "reason_rejected": "Both objects recede from each other, guaranteeing a non‑zero relative speed and thus a Doppler shift."
    }
  ]
}
